@startuml

class Product {
  + Name : string
  + Description : string
  + NetPrice : double
}

class Country {
  + Name : string
  + VATRate : float
  + Currency : string
  + ConversionRateToEuro : float
}

class Representative {
  + FirstName : string
  + LastName : string
  + SocialSecurityNumber : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Customer {
  + Name : string
  + Address : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Order {
  + OrderID : string
  + Quantity : int
  + OrderDate : date
  + DesiredDeliveryDate : date
}

class Manufacturer {
  + Name : string
}

Product "*" -- "1" Manufacturer : manufacturedBy
Product "*" -- "1" Country : soldIn
Representative "1" -- "1" Country : responsibleFor
Customer "*" -- "*" Country : resellsIn
Representative "1" -- "*" Order : places
Order "*" -- "1" Product : refersTo

@enduml

